package main

import "fmt"

func classify(timeout bool, retries int) (string, string) {
	timeoutKind := "none"
	if timeout { timeoutKind = "error" }
	retryKind := "none"
	if retries < 0 { retryKind = "bug" }
	return timeoutKind, retryKind
}

